def seed_gebaeude(c):
    ins = upd = 0
    for g in GEBAEUDE_DATA:
        c.execute("SELECT id FROM gebaeude_typen WHERE id=?", (g["id"],))
        exists = c.fetchone()
        vals = {k: (json.dumps(v, ensure_ascii=False) if k in JSON_FIELDS and isinstance(v, (dict, list))
                   else (int(v) if k in BOOL_FIELDS else v))
               for k, v in g.items()}
        if exists:
            sp = [f"{k}=?" for k in vals if k != "id"]
            c.execute(f"UPDATE gebaeude_typen SET {','.join(sp)},updated_at=CURRENT_TIMESTAMP WHERE id=?",
                      [vals[k] for k in vals if k != "id"] + [g["id"]])
            upd += 1
        else:
            cols = list(vals.keys())
            c.execute(f"INSERT INTO gebaeude_typen ({','.join(cols)}) VALUES ({','.join(['?']*len(cols))})",
                      [vals[k] for k in cols])
            print(f"  ✅  ID {g['id']:>3} | {g['name']} – neu")
            ins += 1
    return ins, upd

def seed_vorkommen(c):
    ins = upd = 0
    for v in VORKOMMEN_DATA:
        fw = json.dumps(v["findwahrscheinlichkeit"], ensure_ascii=False)
        c.execute("SELECT id FROM vorkommen WHERE id=?", (v["id"],))
        if c.fetchone():
            c.execute("UPDATE vorkommen SET name=?,typ=?,tech=?,suchkosten=?,beschreibung=?,"
                      "findwahrscheinlichkeit=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",
                      (v["name"],v["typ"],v["tech"],v["suchkosten"],v["beschreibung"],fw,v["id"]))
            print(f"  🔄  ID {v['id']:>2} | {v['name']:<15} ({v['typ']}) – aktualisiert"); upd+=1
        else:
            c.execute("INSERT INTO vorkommen (id,name,typ,tech,suchkosten,beschreibung,findwahrscheinlichkeit) VALUES (?,?,?,?,?,?,?)",
                      (v["id"],v["name"],v["typ"],v["tech"],v["suchkosten"],v["beschreibung"],fw))
            print(f"  ✅  ID {v['id']:>2} | {v['name']:<15} ({v['typ']}) – neu"); ins+=1
    return ins, upd

def seed_ressourcen(c):
    ins = upd = 0
    for (rid,name,typ,wert,verbrauch,platz) in RESSOURCEN_DATA:
        c.execute("SELECT id FROM ressourcen WHERE id=?", (rid,))
        if c.fetchone():
            c.execute("UPDATE ressourcen SET name=?,typ=?,wert=?,verbrauch=?,platzbedarf=?,"
                      "updated_at=CURRENT_TIMESTAMP WHERE id=?", (name,typ,wert,verbrauch,platz,rid))
            upd += 1
        else:
            c.execute("INSERT INTO ressourcen (id,name,typ,wert,verbrauch,platzbedarf) VALUES (?,?,?,?,?,?)",
                      (rid,name,typ,wert,verbrauch,platz))
            ins += 1
    return ins, upd

def seed():
    conn = sqlite3.connect(DB_PATH); conn.row_factory = sqlite3.Row
    init_tables(conn); c = conn.cursor()
    print("\n🔹 Gebäude-Typen:")
    g_ins, g_upd = seed_gebaeude(c)
    print(f"   → {g_ins} neu, {g_upd} aktualisiert")
    print("\n🔹 Vorkommen:")
    v_ins, v_upd = seed_vorkommen(c)
    print("\n🔹 Ressourcen:")
    r_ins, r_upd = seed_ressourcen(c)
    conn.commit(); conn.close()
    print(f"\n🏁 Gebäude:    {g_ins} neu, {g_upd} aktualisiert")
    print(f"🏁 Vorkommen:  {v_ins} neu, {v_upd} aktualisiert")
    print(f"🏁 Ressourcen: {r_ins} neu, {r_upd} aktualisiert")

if __name__ == "__main__":
    print("🌱 Seed v5.7: 108 Gebäude + 20 Vorkommen + 65 Ressourcen\n")
    seed()
